mapper.select:
    SELECT    
	      todo.BOOKSET_ID
    FROM BOK_BATCH_TASK_TODO todo
    LEFT JOIN BOK_BOOKSET bookset ON todo.BOOKSET_ID = bookset.BOOKSET_ID
    LEFT JOIN SYS_BATCH_TASK task ON task.TASK_ID = todo.TASK_ID      
    WHERE 1=1  
    AND todo.SEQ_NO = #{seqNo}
    AND todo.TASK_ID = #{taskId}  
    AND todo.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}

SELECT bs.SUBJECT_NO, bs.BASE_SUBJECT_NATURE FROM BOK_SUBJECT bs,BOK_BOOKSET bb WHERE bb.BOOKSET_ID = #{booksetId} AND bb.BOOKSET_ID_TMPL = bs.BOOKSET_ID AND bs.SUBJECT_LEVEL = 3
AND bs.BASE_SUBJECT_NATURE IN
#{item}
